ST.xhtml:
parts.timing(
    operatorStatus_ref := operatorStatus_ref,
    config_ref := config.timing);
parts.mercatorMeteo( config_ref := config.mercatorMeteo );
parts.configManager( isEnabled := operatorStatus_ref = OperatorStatus.tech );
statuses.healthStatus := F_HealthStatus(
    superState := TRUE,
    isGood := (parts.timing.statuses.healthStatus = HealthStatus.good) AND (parts.mercatorMeteo.statuses.healthStatus = HealthStatus.good),
    hasWarning := (parts.timing.statuses.healthStatus = HealthStatus.warning) OR (parts.mercatorMeteo.statuses.healthStatus = HealthStatus.warning));
statuses.busyStatus := F_BusyStatus(
    superState := TRUE,
    isBusy := statuses.initializationStatus = InitializationStatus.initializing);
processes.initialize( isEnabled := (statuses.initializationStatus = InitializationStatus.shutdown) OR ((statuses.initializationStatus = InitializationStatus.initializingFailed) OR (statuses.initializationStatus = InitializationStatus.initialized)) );
processes.lock( isEnabled := (operatorStatus_ref = OperatorStatus.tech) AND (statuses.initializationStatus = InitializationStatus.initialized) );
processes.unlock( isEnabled := (operatorStatus_ref = OperatorStatus.tech) AND (statuses.initializationStatus = InitializationStatus.locked) );
processes.changeOperatingState( isEnabled := FALSE );

statuses.healthStatus := F_HealthStatus(
    superState := TRUE,
    hasWarning := FALSE,
    isGood := isNtpConnected AND isNtpSynchronized);
ntpExtTime_ro := ntpExtTime;
isNtpConnected_ro := isNtpConnected;
isNtpSynchronized_ro := isNtpSynchronized;
